{
  "title": "旧算盘",
  "lines": [
    "十三桥子记年长",
    "珠走声中练算忙",
    "此日算清无更用",
    "机关解尽挂空墙"
  ],
  "intention": "写旧算盘曾帮助人学习计算、成长，如今算清无更用，被解尽机关挂空墙；不以感叹岁月流逝作结。",
  "allusion": {
    "card_id": "wang-quan",
    "mode": "翻用",
    "relation": "典源《庄子·外物》得鱼忘筌，原义是工具完成使命后可以不执着于工具，带有得鱼后忘筌的正面超脱。本诗翻用其义：算盘帮助成长后，今日算清无更用，机关解尽挂空墙，不是忘恩，而是工具使命完成后的退出；新立场侧重器物本身在完成使命后的闲置，不指责人物忘恩。"
  }
}

{
  "reading": "旧算盘曾陪伴主人多年，在珠算声中帮助练习计算；如今账目已清，不再需要它，于是把算珠机关解开，挂在空墙上。诗以算盘为线索，写器物完成使命后的闲置，但末句‘机关解尽挂空墙’带有主动解卸的意味，并非单纯感叹岁月。",
  "references": [
    {
      "card_id": "wang-quan",
      "quote": "此日算清无更用",
      "function": "暗用‘得鱼忘筌’的寓意，将算盘比作完成计算任务的工具；算清之后不再使用，体现工具完成使命后可以舍弃。但正文没有明确说要忘记或否定工具，只是陈述‘无更用’，因此是用典的淡化处理。",
      "direction": "顺用"
    }
  ],
  "issues": [
    {
      "quote": "机关解尽挂空墙",
      "problem": "‘机关解尽’可能暗示主动拆解算盘，但前文未交代拆解的原因或过程，容易让读者理解为算盘被破坏而非闲置；与‘不再适用’的题意略有偏差。",
      "repair": "可改为更中性的悬挂状态，如‘闲挂空墙’或‘尘满空墙’，避免‘解尽’带来的主动拆解歧义。"
    }
  ],
  "decision": "revise"
}

{
  "title": "拒聘归舍",
  "lines": [
    "华轩众羡聘书来，",
    "俯仰随人失步才。",
    "曳尾宁辞楚庙贵，",
    "柴门自扫旧尘埃。"
  ],
  "intention": "写一个人拒绝众人羡慕的体面安排，因为答应便要按他人节拍行事，失去自主做事的余地；他甘愿回到简陋日常，自行打理手头事务。",
  "allusion": {
    "card_id": "ye-wei",
    "mode": "明用",
    "relation": "第三句暗用《庄子·秋水》庄子辞楚王聘、愿曳尾涂中事：原典在死后留骨受尊与活着泥中行走间取后者；本诗借“曳尾”与“楚庙贵”的对照，表明拒绝并非不识抬举，而是算清自主承受比被供奉更重。新在将典源的选择落在眼前聘书与日常洒扫之间。"
  }
}
